arguments.command:
cd /app; sed -i 's|^include_HEADERS.*|isodurincludedir = $(includedir)/isodur\nisodurinclude_HEADERS = include/isodur/isodur.h|;s|^nodist_include_HEADERS.*|nodist_isodurinclude_HEADERS = include/isodur/version.h|' Makefile.am
cd /tmp/b && rm -rf * && cp -r /app src && cd src && autoreconf -fi 2>&1 | grep -i warn; mkdir ../bd && cd ../bd && ../src/configure --prefix=/tmp/p >/dev/null && make distcheck 2>&1 | tail -3; make >/dev/null; make install >/dev/null; cd /tmp; cat > t.c <<'E'
#include <isodur/isodur.h>
#include <stdio.h>
int main(){puts(isodur_version());}
E
for s in "" --static; do gcc t.c $(pkg-config --cflags --libs $s isodur) -o t PKG_CONFIG_PATH 2>/dev/null; PKG_CONFIG_PATH=/tmp/p/lib/pkgconfig; export PKG_CONFIG_PATH; gcc t.c $(pkg-config --cflags --libs $s isodur) -o t && LD_LIBRARY_PATH=/tmp/p/lib ./t; done; /tmp/p/bin/durfmt PT90M
